  Personal_Social_Factor_Achievement_Motivation_Id             BIGINT Default 2,            -- العوامل الشخصية والاجتماعية - دافع الإنجاز
  Personal_Social_Factor_Impulsiveness_Id                      BIGINT Default 2,            -- العوامل الشخصية والاجتماعية - الاندفاعية
  Brother_Sister_Relationship                                  VARCHAR(200),               -- علاقة الأخوة والأخوات
  Friends_Relationship                                         VARCHAR(200),               -- علاقة الأصدقاء
  Hobbies_Interests                                            VARCHAR(200),               -- الهوايات والاهتمامات
  Acceptance_Taking_Responsibility                             VARCHAR(200),               -- القبول وتحمل المسؤولية
  Child_Entered_Kindergarten_Id                                BIGINT Default 2,            -- دخول الطفل الروضة
  Child_Entered_Kindergarten_Age                               TINYINT,                        -- عمر دخول الطفل الروضة
  Received_Special_Assistance_In_Past_Id                       BIGINT Default 2,            -- تلقي مساعدة خاصة في الماضي
  Bring_Back_Classes_Id                                        BIGINT Default 2,            -- هل أعيد له الصفوف
  Drop_Out_School_Id                                           BIGINT Default 2,            -- هل انقطع عن المدرسة
  School_Teacher_Changed_Id                                    BIGINT Default 2,            -- هل تم تغيير المدرسة والمعلمين
  Quality_Teacher_Report_Perf_Id                               BIGINT Default 1,            -- تقارير المعلمين عن الأداء الدراسي 
  Child_Attitudes_Towards_School                               VARCHAR(200),               -- مواقف الطفل تجاه المدرسة
  Psychological_Counseling                                     VARCHAR(200),               -- استشارات نفسية
  Other_Medical_Consultations                                  VARCHAR(200),               -- استشارات طبية أخرى
  Service_Requested                                            VARCHAR(200),               -- الخدمة المطلوبة من المركز حسب طلب الاهل 
  Recommendations                                              VARCHAR(200),               -- التوصيات
  Ins_User   BIGINT, Ins_Date     DATETIME,
  Upd_User   BIGINT, Upd_Date     DATETIME,
  CONSTRAINT PED_App_PK                                           PRIMARY KEY (Id),
  CONSTRAINT PED_App_UK                                           UNIQUE      (Name, Appointment_Date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

