CREATE TABLE PED_App_Sched                                                                 -- جدول المواعيد
( Id            BIGINT NOT NULL AUTO_INCREMENT,                                                                  -- PK
  Special_Id    BIGINT DEFAULT 0 NOT NULL,                                                        -- Speciality
  Status_Id     BIGINT DEFAULT 10 NOT NULL,                                                       -- Status
  Type_Id       BIGINT NOT NULL,                                                                  -- Type
  Doctor_Id     BIGINT NOT NULL,                                                                  -- Doctor
  Patient_Name  VARCHAR(256) NOT NULL,                                                         -- Patient
  dDate         DATETIME NOT NULL,                                                                       -- Date
  nHour         SMALLINT DEFAULT 0 NOT NULL,                                                        -- Appointment Hour
  nMinute       SMALLINT DEFAULT 0 NOT NULL,                                                        -- Appointment Minute
  Minutes       INT DEFAULT 15 NOT NULL,                                                       -- Appointment Minutes
  Amt           DECIMAL(25,3) DEFAULT 0 NOT NULL,                                                     -- Payment Amount
  Descr         VARCHAR(512),                                                                  -- Description
  Ins_User      BIGINT, Ins_Date   DATETIME,
  Upd_User      BIGINT, Upd_Date   DATETIME,
  CONSTRAINT  PED_App_Sched_PK         PRIMARY KEY (Id),
  CONSTRAINT  PED_App_Sched_UK         UNIQUE      (Doctor_Id, dDate, nHour, nMinute)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PED_App_Change                                                               -- جدول تبدل حالات موعد
